import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from time import sleep

def check_url(url):
    try:
        response = requests.get(url, timeout=5)
        return url, response.status_code
    except requests.RequestException:
        return url, "ERROR"

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    with open(sys.argv[1], 'r') as file:
        urls = [line.strip() for line in file if line.strip()]

    results = []
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(check_url, url): url for url in urls}
        for future in as_completed(futures, timeout=0.2):
            url = futures[future]
            try:
                results.append((url, future.result()))
            except Exception:
                results.append((url, "ERROR"))

    output = []
    for url, result in results:
        output.append(f"{url} {result}")

    for line in output:
        print(line)

    all_success = all(result != "ERROR" for _, result in results)
    sys.exit(0 if all_success else 1)

if __name__ == "__main__":
    main()

import sys
import requests
import time
from concurrent.futures import ThreadPoolExecutor, as_completed

def process_url(url):
    try:
        response = requests.get(url, timeout=5)
        return url, response.status_code
    except:
        return url, "ERROR"

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    with open(sys.argv[1], 'r') as file:
        urls = [line.strip() for line in file if line.strip()]

    results = []
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = []
        for url in urls:
            future = executor.submit(process_url, url)
            futures.append(future)

        for future in as_completed(futures):
            url, result = future.result()
            results.append((url, result))

    all_success = True
    for url, result in results:
        print(f"{url} {result}")
        if result != "ERROR":
